<?php
/** Enterprise accommodation domain: nightly inventory, reservations and PMS operations. */

final class UthengaAccommodationPermissions
{
    private const ALL_PERMISSIONS = [
        'property.read','property.write','inventory.read','inventory.write',
        'reservation.read','reservation.write','stay.write','stay.balance_override',
        'task.read','task.write','staff.write','finance.read','payment.write',
        'refund.request','audit.read',
    ];

    private const ROLE_PERMISSIONS = [
        'OWNER' => ['*'],
        'GENERAL_MANAGER' => ['property.read','property.write','inventory.read','inventory.write','reservation.read','reservation.write','stay.write','stay.balance_override','task.read','task.write','staff.write','finance.read','payment.write','refund.request','audit.read'],
        'FRONT_DESK' => ['property.read','inventory.read','reservation.write','stay.write','task.read','payment.write'],
        'RESERVATIONS' => ['property.read','inventory.read','inventory.write','reservation.write'],
        'HOUSEKEEPING' => ['property.read','reservation.read','task.write'],
        'MAINTENANCE' => ['property.read','inventory.read','task.write'],
        'FINANCE' => ['property.read','reservation.read','finance.read','payment.write','refund.request','audit.read'],
        'AUDITOR' => ['property.read','inventory.read','reservation.read','finance.read','audit.read'],
    ];

    public static function allows(string $role, string $permission): bool
    {
        $grants = self::ROLE_PERMISSIONS[$role] ?? [];
        return in_array('*', $grants, true) || in_array($permission, $grants, true);
    }

    public static function roles(): array { return array_keys(self::ROLE_PERMISSIONS); }

    public static function capabilities(string $role): array
    {
        $grants = self::ROLE_PERMISSIONS[$role] ?? [];
        return in_array('*', $grants, true) ? self::ALL_PERMISSIONS : array_values($grants);
    }
}

final class UthengaAccommodationContracts
{
    public static function text($value, int $max, bool $required = false): string
    {
        $value = trim(is_scalar($value) ? (string) $value : '');
        if ($required && $value === '') throw UthengaTieErrors::validation(['value' => 'A required value is missing.']);
        return mb_substr($value, 0, $max);
    }

    public static function id($value, string $field = 'id'): string
    {
        $value = trim((string) $value);
        if (!preg_match('/^[A-Za-z0-9_-]{1,64}$/', $value) && !preg_match('/^[a-f0-9-]{36}$/i', $value)) throw UthengaTieErrors::validation([$field => 'Choose a valid record.']);
        return $value;
    }

    public static function integer($value, int $min, int $max, string $field): int
    {
        $parsed = filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => $min, 'max_range' => $max]]);
        if ($parsed === false) throw UthengaTieErrors::validation([$field => "Use a whole number between {$min} and {$max}."]);
        return (int) $parsed;
    }

    public static function decimal($value, float $min, float $max, string $field): float
    {
        if (!is_numeric($value) || (float) $value < $min || (float) $value > $max) throw UthengaTieErrors::validation([$field => 'Use a valid amount.']);
        return round((float) $value, 2);
    }

    public static function dates($checkIn, $checkOut): array
    {
        try { $start = new DateTimeImmutable((string) $checkIn); $end = new DateTimeImmutable((string) $checkOut); }
        catch (Throwable $error) { throw UthengaTieErrors::validation(['dates' => 'Use valid check-in and check-out dates.']); }
        $start = $start->setTime(0, 0); $end = $end->setTime(0, 0);
        $nights = (int) $start->diff($end)->days;
        if ($end <= $start || $nights < 1 || $nights > 365) throw UthengaTieErrors::validation(['dates' => 'A stay must contain between 1 and 365 nights.']);
        $dates = []; for ($date = $start; $date < $end; $date = $date->modify('+1 day')) $dates[] = $date->format('Y-m-d');
        return ['check_in' => $start->format('Y-m-d'), 'check_out' => $end->format('Y-m-d'), 'nights' => $nights, 'dates' => $dates];
    }
}

final class UthengaAccommodationService
{
    public function __construct(private PDO $db) {}

    public function portfolio(string $actorId): array
    {
        $stmt = $this->db->prepare("SELECT DISTINCT p.*, CASE WHEN p.vendor_id=? THEN 'OWNER' ELSE m.role_key END access_role
            FROM tie_accommodation_properties p
            LEFT JOIN tie_accommodation_staff_memberships m ON m.property_id=p.id AND m.user_id=? AND m.status='ACTIVE'
            WHERE p.vendor_id=? OR m.user_id=? ORDER BY p.updated_at DESC");
        $stmt->execute([$actorId, $actorId, $actorId, $actorId]);
        $properties = [];
        foreach ($stmt->fetchAll() as $row) $properties[] = $this->publicProperty($row);
        return ['schema_version' => 'tie-accommodation-portfolio/v2', 'properties' => $properties, 'roles' => UthengaAccommodationPermissions::roles()];
    }

    public function dashboard(string $propertyId, string $actorId): array
    {
        $property = $this->access($propertyId, $actorId, 'property.read');
        $today = (new DateTimeImmutable('now', new DateTimeZone((string) $property['timezone'])))->format('Y-m-d');
        $tomorrow = (new DateTimeImmutable($today))->modify('+1 day')->format('Y-m-d');
        $this->ensureInventory($propertyId, $today, (new DateTimeImmutable($today))->modify('+30 day')->format('Y-m-d'));
        $metrics = $this->db->prepare("SELECT
            COALESCE(SUM(capacity_rooms),0) capacity_nights,
            COALESCE(SUM(confirmed_rooms),0) occupied_nights,
            COALESCE(SUM(GREATEST(0,capacity_rooms-blocked_rooms-held_rooms-confirmed_rooms)),0) sellable_nights
            FROM tie_accommodation_inventory_nights WHERE property_id=? AND stay_date=?");
        $metrics->execute([$propertyId, $today]); $inventory = $metrics->fetch() ?: [];
        $reservations = $this->db->prepare("SELECT COUNT(*) total,
            SUM(status='PENDING_APPROVAL') pending,
            SUM(check_in_date=? AND status IN ('CONFIRMED','CHECKED_IN')) arrivals,
            SUM(check_out_date=? AND status IN ('CONFIRMED','CHECKED_IN')) departures
            FROM tie_accommodation_reservations WHERE property_id=?");
        $reservations->execute([$today, $today, $propertyId]); $summary = $reservations->fetch() ?: [];
        $revenue = $this->db->prepare("SELECT COALESCE(SUM(t.amount),0)
            FROM transactions t
            INNER JOIN tie_accommodation_reservations r ON r.booking_id=t.booking_id
            WHERE r.property_id=? AND DATE(t.transaction_date)=?
              AND LOWER(t.status) IN ('success','completed','captured','paid')");
        $revenue->execute([$propertyId,$today]);
        $tasks = $this->db->prepare("SELECT COUNT(*) total, SUM(status='OPEN') open_count, SUM(priority='URGENT' AND status IN ('OPEN','IN_PROGRESS')) urgent_count FROM tie_accommodation_unit_tasks WHERE property_id=?");
        $tasks->execute([$propertyId]); $taskSummary = $tasks->fetch() ?: [];
        $recent = $this->db->prepare("SELECT r.*, rr.room_type_id, rt.room_name, rr.quantity FROM tie_accommodation_reservations r INNER JOIN tie_accommodation_reservation_rooms rr ON rr.reservation_id=r.id INNER JOIN room_types rt ON rt.id=rr.room_type_id WHERE r.property_id=? ORDER BY r.created_at DESC LIMIT 12");
        $recent->execute([$propertyId]);
        $arrivals = $this->db->prepare("SELECT r.id,r.reservation_code,r.guest_name,r.check_in_date,r.check_out_date,r.status,rt.room_name,rr.quantity FROM tie_accommodation_reservations r INNER JOIN tie_accommodation_reservation_rooms rr ON rr.reservation_id=r.id INNER JOIN room_types rt ON rt.id=rr.room_type_id WHERE r.property_id=? AND r.check_in_date BETWEEN ? AND ? AND r.status IN ('PENDING_APPROVAL','CONFIRMED','CHECKED_IN') ORDER BY r.check_in_date,r.created_at LIMIT 20");
        $arrivals->execute([$propertyId, $today, $tomorrow]);
        $capacity = (int) ($inventory['capacity_nights'] ?? 0); $occupied = (int) ($inventory['occupied_nights'] ?? 0);
        return ['schema_version' => 'tie-accommodation-dashboard/v2', 'property' => $this->publicProperty($property),
            'metrics' => ['rooms_today' => $capacity, 'occupied_today' => $occupied, 'sellable_today' => (int) ($inventory['sellable_nights'] ?? 0), 'occupancy_percent' => $capacity ? round($occupied / $capacity * 100, 1) : null, 'reservations' => (int) ($summary['total'] ?? 0), 'pending' => (int) ($summary['pending'] ?? 0), 'arrivals' => (int) ($summary['arrivals'] ?? 0), 'departures' => (int) ($summary['departures'] ?? 0), 'today_revenue' => (float) $revenue->fetchColumn(), 'currency' => $property['currency'], 'open_tasks' => (int) ($taskSummary['open_count'] ?? 0), 'urgent_tasks' => (int) ($taskSummary['urgent_count'] ?? 0)],
            'recent_reservations' => array_map([$this, 'publicReservation'], $recent->fetchAll()), 'upcoming_arrivals' => $arrivals->fetchAll(), 'generated_at' => gmdate('c')];
    }

    public function setup(string $propertyId, string $actorId, array $input, string $correlationId): array
    {
        $before = $this->access($propertyId, $actorId, 'property.write', true);
        $name = UthengaAccommodationContracts::text($input['name'] ?? '', 180, true); $address = UthengaAccommodationContracts::text($input['address'] ?? '', 255, true);
        $type = strtoupper(UthengaAccommodationContracts::text($input['property_type'] ?? 'HOTEL', 30));
        if (!in_array($type, ['HOTEL','LODGE','GUESTHOUSE','HOSTEL','SERVICED_APARTMENT'], true)) throw UthengaTieErrors::validation(['property_type' => 'Choose a supported nightly lodging type.']);
        $version = UthengaAccommodationContracts::integer($input['version'] ?? 0, 1, PHP_INT_MAX, 'version');
        $stmt = $this->db->prepare('UPDATE tie_accommodation_properties SET name=?,property_type=?,description=?,address=?,city=?,phone=?,email=?,image_url=?,check_in_time=?,check_out_time=?,version=version+1 WHERE id=? AND version=?');
        $stmt->execute([$name,$type,UthengaAccommodationContracts::text($input['description'] ?? '',5000),$address,UthengaAccommodationContracts::text($input['city'] ?? '',120),UthengaAccommodationContracts::text($input['phone'] ?? '',60),UthengaAccommodationContracts::text($input['email'] ?? '',190),UthengaAccommodationContracts::text($input['image_url'] ?? '',500),$this->time($input['check_in_time'] ?? '14:00'),$this->time($input['check_out_time'] ?? '10:00'),$propertyId,$version]);
        if ($stmt->rowCount() !== 1) throw UthengaTieErrors::validation(['version' => 'Property settings changed in another session. Refresh and try again.']);
        if (!empty($before['listing_id'])) $this->db->prepare('UPDATE listings SET title=?,description=?,location=?,image=IF(?="",image,?) WHERE id=? AND vendor_id=?')->execute([$name,UthengaAccommodationContracts::text($input['description'] ?? '',5000),$address,UthengaAccommodationContracts::text($input['image_url'] ?? '',500),UthengaAccommodationContracts::text($input['image_url'] ?? '',500),$before['listing_id'],$before['vendor_id']]);
        $after = $this->propertyRow($propertyId); $this->audit($propertyId,$actorId,'property.updated','property',$propertyId,$correlationId,$before,$after);
        return $this->publicProperty($after);
    }

    public function rooms(string $propertyId, string $actorId): array
    {
        $this->access($propertyId, $actorId, 'property.read');
        $rooms = $this->db->prepare('SELECT rt.*, (SELECT COUNT(*) FROM tie_accommodation_units u WHERE u.room_type_id=rt.id AND u.is_active=1) unit_count FROM room_types rt WHERE rt.property_id=? ORDER BY rt.is_active DESC,rt.sort_order,rt.id'); $rooms->execute([$propertyId]);
        $units = $this->db->prepare('SELECT u.*,rt.room_name FROM tie_accommodation_units u INNER JOIN room_types rt ON rt.id=u.room_type_id WHERE u.property_id=? ORDER BY u.unit_code'); $units->execute([$propertyId]);
        $rates = $this->db->prepare('SELECT rp.*,cp.name cancellation_policy_name,cp.free_cancel_hours,cp.penalty_percent,cp.no_show_percent FROM tie_accommodation_rate_plans rp INNER JOIN tie_accommodation_cancellation_policies cp ON cp.id=rp.cancellation_policy_id WHERE rp.property_id=? ORDER BY rp.is_active DESC,rp.name'); $rates->execute([$propertyId]);
        $policies = $this->db->prepare('SELECT * FROM tie_accommodation_cancellation_policies WHERE property_id=? ORDER BY is_active DESC,name,id'); $policies->execute([$propertyId]);
        return ['schema_version' => 'tie-accommodation-rooms/v2','rooms'=>$rooms->fetchAll(),'units'=>$units->fetchAll(),'rate_plans'=>$rates->fetchAll(),'cancellation_policies'=>$policies->fetchAll()];
    }

    public function saveUnit(string $propertyId, string $actorId, array $input, string $correlationId): array
    {
        $this->access($propertyId,$actorId,'property.write'); $roomTypeId=UthengaAccommodationContracts::integer($input['room_type_id']??null,1,PHP_INT_MAX,'room_type_id'); $this->room($propertyId,$roomTypeId);
        $code=UthengaAccommodationContracts::text($input['unit_code']??'',80,true); $id=$this->uuid();
        $stmt=$this->db->prepare('INSERT INTO tie_accommodation_units (id,property_id,room_type_id,unit_code,unit_name,floor_label) VALUES (?,?,?,?,?,?)');
        try {$stmt->execute([$id,$propertyId,$roomTypeId,$code,UthengaAccommodationContracts::text($input['unit_name']??'',160),UthengaAccommodationContracts::text($input['floor_label']??'',80)]);} catch(PDOException $error){if($error->getCode()==='23000')throw UthengaTieErrors::validation(['unit_code'=>'That room or unit code already exists.']);throw $error;}
        $row=$this->unit($propertyId,$id); $this->audit($propertyId,$actorId,'unit.created','unit',$id,$correlationId,null,$row); return $row;
    }

    public function saveRatePlan(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'inventory.write'); $roomTypeId=UthengaAccommodationContracts::integer($input['room_type_id']??null,1,PHP_INT_MAX,'room_type_id'); $this->room($propertyId,$roomTypeId);
        $booking=strtoupper(UthengaAccommodationContracts::text($input['booking_mode']??'INSTANT',20)); $payment=strtoupper(UthengaAccommodationContracts::text($input['payment_mode']??'FULL',20));
        if(!in_array($booking,['INSTANT','REQUEST'],true)||!in_array($payment,['FULL','DEPOSIT'],true))throw UthengaTieErrors::validation(['rate_plan'=>'Choose supported booking and payment modes.']);
        $deposit=$payment==='DEPOSIT'?UthengaAccommodationContracts::decimal($input['deposit_percent']??null,1,99,'deposit_percent'):null;
        $policyId=trim((string)($input['cancellation_policy_id']??''));if($policyId===''){$policy=$this->db->prepare('SELECT id FROM tie_accommodation_cancellation_policies WHERE property_id=? AND is_active=1 ORDER BY created_at,id LIMIT 1');$policy->execute([$propertyId]);$policyId=(string)$policy->fetchColumn();}if($policyId==='')throw UthengaTieErrors::validation(['policy'=>'Create an active cancellation policy first.']);$this->policy($propertyId,$policyId);
        $id=$this->uuid();$this->db->prepare('INSERT INTO tie_accommodation_rate_plans (id,property_id,room_type_id,cancellation_policy_id,name,base_rate,booking_mode,payment_mode,deposit_percent,minimum_stay,maximum_stay) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$propertyId,$roomTypeId,$policyId,UthengaAccommodationContracts::text($input['name']??'',160,true),UthengaAccommodationContracts::decimal($input['base_rate']??null,0.01,100000000,'base_rate'),$booking,$payment,$deposit,UthengaAccommodationContracts::integer($input['minimum_stay']??1,1,365,'minimum_stay'),UthengaAccommodationContracts::integer($input['maximum_stay']??30,1,365,'maximum_stay')]);
        $row=$this->ratePlan($propertyId,$id);$this->audit($propertyId,$actorId,'rate_plan.created','rate_plan',$id,$correlationId,null,$row);return $row;
    }

    public function updateRoomType(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'inventory.write');$id=UthengaAccommodationContracts::integer($input['room_type_id']??null,1,PHP_INT_MAX,'room_type_id');$version=UthengaAccommodationContracts::integer($input['version']??0,1,PHP_INT_MAX,'version');$owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();
        try{$before=$this->room($propertyId,$id,true);$total=UthengaAccommodationContracts::integer($input['total_rooms']??$before['total_rooms'],1,10000,'total_rooms');$max=UthengaAccommodationContracts::integer($input['max_occupancy']??$before['max_occupancy'],1,50,'max_occupancy');$adults=UthengaAccommodationContracts::integer($input['adults_capacity']??$before['adults_capacity'],1,$max,'adults_capacity');$children=UthengaAccommodationContracts::integer($input['children_capacity']??$before['children_capacity'],0,$max,'children_capacity');if($adults+$children<$max)$children=$max-$adults;
            $future=$this->db->prepare('SELECT blocked_rooms,held_rooms,confirmed_rooms FROM tie_accommodation_inventory_nights WHERE room_type_id=? AND stay_date>=CURDATE() FOR UPDATE');$future->execute([$id]);foreach($future->fetchAll() as $night)if((int)$night['blocked_rooms']+(int)$night['held_rooms']+(int)$night['confirmed_rooms']>$total)throw UthengaTieErrors::validation(['total_rooms'=>'Capacity cannot be reduced below committed or blocked nightly inventory.']);
            $u=$this->db->prepare('UPDATE room_types SET room_name=?,description=?,price_per_night=?,total_rooms=?,available_rooms=?,max_occupancy=?,adults_capacity=?,children_capacity=?,amenities=?,version=version+1 WHERE id=? AND property_id=? AND version=? AND is_active=1');$amenities=is_array($input['amenities']??null)?array_values(array_slice(array_filter(array_map(fn($v)=>UthengaAccommodationContracts::text($v,80),$input['amenities'])),0,50)):(json_decode((string)($before['amenities']??'[]'),true)?:[]);$u->execute([UthengaAccommodationContracts::text($input['room_name']??$before['room_name'],120,true),UthengaAccommodationContracts::text($input['description']??$before['description'],2000),UthengaAccommodationContracts::decimal($input['price_per_night']??$before['price_per_night'],0.01,100000000,'price_per_night'),$total,$total,$max,$adults,$children,json_encode($amenities),$id,$propertyId,$version]);if($u->rowCount()!==1)throw UthengaTieErrors::validation(['version'=>'Room type changed in another session. Refresh and retry.']);$this->db->prepare('UPDATE tie_accommodation_inventory_nights SET capacity_rooms=?,version=version+1 WHERE room_type_id=? AND stay_date>=CURDATE()')->execute([$total,$id]);$after=$this->room($propertyId,$id);$this->audit($propertyId,$actorId,'room_type.updated','room_type',(string)$id,$correlationId,$before,$after);if($owns)$this->db->commit();return $after;
        }catch(Throwable $error){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $error;}
    }

    public function deactivateRoomType(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'inventory.write');$id=UthengaAccommodationContracts::integer($input['room_type_id']??null,1,PHP_INT_MAX,'room_type_id');$version=UthengaAccommodationContracts::integer($input['version']??0,1,PHP_INT_MAX,'version');$owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();try{$before=$this->room($propertyId,$id,true);$committed=$this->db->prepare('SELECT COALESCE(SUM(held_rooms+confirmed_rooms),0) FROM tie_accommodation_inventory_nights WHERE room_type_id=? AND stay_date>=CURDATE() FOR UPDATE');$committed->execute([$id]);if((int)$committed->fetchColumn()>0)throw UthengaTieErrors::validation(['room_type'=>'A room type with future held or confirmed inventory cannot be deactivated.']);$dependencies=$this->db->prepare('SELECT (SELECT COUNT(*) FROM tie_accommodation_units WHERE room_type_id=? AND is_active=1)+(SELECT COUNT(*) FROM tie_accommodation_rate_plans WHERE room_type_id=? AND is_active=1)');$dependencies->execute([$id,$id]);if((int)$dependencies->fetchColumn()>0)throw UthengaTieErrors::validation(['room_type'=>'Deactivate its physical units and rate plans first.']);$u=$this->db->prepare('UPDATE room_types SET is_active=0,version=version+1 WHERE id=? AND property_id=? AND version=?');$u->execute([$id,$propertyId,$version]);if($u->rowCount()!==1)throw UthengaTieErrors::validation(['version'=>'Room type changed in another session. Refresh and retry.']);$after=$before;$after['is_active']=0;$after['version']=$version+1;$this->audit($propertyId,$actorId,'room_type.deactivated','room_type',(string)$id,$correlationId,$before,$after);if($owns)$this->db->commit();return $after;}catch(Throwable $error){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $error;}
    }

    public function updateUnit(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'inventory.write');$id=UthengaAccommodationContracts::id($input['unit_id']??'','unit_id');$version=UthengaAccommodationContracts::integer($input['version']??0,1,PHP_INT_MAX,'version');$owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();try{$before=$this->unit($propertyId,$id,true);$roomTypeId=UthengaAccommodationContracts::integer($input['room_type_id']??$before['room_type_id'],1,PHP_INT_MAX,'room_type_id');$this->room($propertyId,$roomTypeId,true);if($roomTypeId!==(int)$before['room_type_id']){$busy=$this->db->prepare("SELECT (SELECT COUNT(*) FROM tie_accommodation_assignments WHERE unit_id=? AND released_at IS NULL)+(SELECT COUNT(*) FROM tie_accommodation_unit_blocks WHERE unit_id=? AND status='ACTIVE')");$busy->execute([$id,$id]);if((int)$busy->fetchColumn()>0)throw UthengaTieErrors::validation(['room_type_id'=>'An assigned or maintenance-blocked unit cannot change room type.']);}$u=$this->db->prepare('UPDATE tie_accommodation_units SET room_type_id=?,unit_code=?,unit_name=?,floor_label=?,version=version+1 WHERE id=? AND property_id=? AND version=? AND is_active=1');try{$u->execute([$roomTypeId,UthengaAccommodationContracts::text($input['unit_code']??$before['unit_code'],80,true),UthengaAccommodationContracts::text($input['unit_name']??$before['unit_name'],160),UthengaAccommodationContracts::text($input['floor_label']??$before['floor_label'],80),$id,$propertyId,$version]);}catch(PDOException $error){if($error->getCode()==='23000')throw UthengaTieErrors::validation(['unit_code'=>'That room or unit code already exists.']);throw $error;}if($u->rowCount()!==1)throw UthengaTieErrors::validation(['version'=>'Physical unit changed in another session. Refresh and retry.']);$after=$this->unit($propertyId,$id);$this->audit($propertyId,$actorId,'unit.updated','unit',$id,$correlationId,$before,$after);if($owns)$this->db->commit();return $after;}catch(Throwable $error){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $error;}
    }

