        $priority=strtoupper(UthengaAccommodationContracts::text($input['priority']??'NORMAL',20));
        if(!in_array($kind,['HOUSEKEEPING','MAINTENANCE','INSPECTION'],true)||!in_array($priority,['LOW','NORMAL','HIGH','URGENT'],true)) throw UthengaTieErrors::validation(['task'=>'Choose a supported task type and priority.']);
        $owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();
        try{
            $id=$this->uuid();
            $this->db->prepare('INSERT INTO tie_accommodation_unit_tasks (id,property_id,unit_id,task_kind,status,priority,assigned_user_id,note,due_at,created_by) VALUES (?,?,?, ?,"OPEN",?,?,?,?,?)')->execute([$id,$propertyId,$unitId,$kind,$priority,($input['assigned_user_id']??'')?:null,UthengaAccommodationContracts::text($input['note']??'',1000),($input['due_at']??'')?:null,$actorId]);
            if($kind==='MAINTENANCE') {
                $start=(string)($input['block_from']??gmdate('Y-m-d'));
                $end=(string)($input['block_until']??'');
                if($end==='') throw UthengaTieErrors::validation(['block_until'=>'Choose the expected return-to-service date.']);
                $this->createUnitBlock($propertyId,$actorId,$unit,$id,$start,$end);
                $this->db->prepare("UPDATE tie_accommodation_units SET operational_status='MAINTENANCE',version=version+1 WHERE id=?")->execute([$unitId]);
            }
            $row=$this->task($propertyId,$id);$this->audit($propertyId,$actorId,'task.created','task',$id,$correlationId,null,$row);if($owns)$this->db->commit();return $row;
        }catch(Throwable $error){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $error;}
    }

    public function updateTask(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'task.write');$id=UthengaAccommodationContracts::id($input['task_id']??'','task_id');$owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();
        try{$before=$this->task($propertyId,$id,true);$status=strtoupper(UthengaAccommodationContracts::text($input['status']??'',20));
        if(!in_array($status,['OPEN','IN_PROGRESS','COMPLETED','CANCELLED'],true))throw UthengaTieErrors::validation(['status'=>'Choose a valid task status.']);
        $version=UthengaAccommodationContracts::integer($input['version']??0,1,PHP_INT_MAX,'version');$u=$this->db->prepare('UPDATE tie_accommodation_unit_tasks SET status=?,completed_at=IF(?="COMPLETED",UTC_TIMESTAMP(),NULL),version=version+1 WHERE id=? AND property_id=? AND version=?');$u->execute([$status,$status,$id,$propertyId,$version]);if($u->rowCount()!==1)throw UthengaTieErrors::validation(['version'=>'Task changed in another session. Refresh and retry.']);
        if(in_array($status,['COMPLETED','CANCELLED'],true)) {
            if($before['task_kind']==='MAINTENANCE') $this->releaseUnitBlock($id,$actorId,$status==='CANCELLED'?'CANCELLED':'RELEASED');
            $unitStatus=$status==='CANCELLED'?'CLEAN_READY':($before['task_kind']==='HOUSEKEEPING'?'CLEAN_READY':($before['task_kind']==='INSPECTION'?'CLEAN_READY':'INSPECTION'));
            $this->db->prepare('UPDATE tie_accommodation_units SET operational_status=?,version=version+1 WHERE id=?')->execute([$unitStatus,$before['unit_id']]);
        }
        $after=$this->task($propertyId,$id);$this->audit($propertyId,$actorId,'task.updated','task',$id,$correlationId,$before,$after);if($owns)$this->db->commit();return $after;}catch(Throwable $error){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $error;}
    }

