    public function updateStaff(string $propertyId,string $actorId,array $input,string $correlationId): array
    {
        $this->access($propertyId,$actorId,'staff.write');$id=UthengaAccommodationContracts::id($input['membership_id']??'','membership_id');$before=$this->membership($propertyId,$id);if($before['role_key']==='OWNER')throw UthengaTieErrors::validation(['membership'=>'Owner access cannot be changed from the staff register.']);$status=strtoupper(UthengaAccommodationContracts::text($input['status']??$before['status'],20));$role=strtoupper(UthengaAccommodationContracts::text($input['role_key']??$before['role_key'],30));if(!in_array($status,['ACTIVE','SUSPENDED','REVOKED'],true))throw UthengaTieErrors::validation(['status'=>'Choose active, suspended or revoked.']);if($status==='ACTIVE'&&empty($before['user_id']))throw UthengaTieErrors::validation(['status'=>'The invited person must create or sign in to their Uthenga account before access can be activated.']);if(!in_array($role,UthengaAccommodationPermissions::roles(),true)||$role==='OWNER')throw UthengaTieErrors::validation(['role_key'=>'Choose a supported staff role.']);$version=UthengaAccommodationContracts::integer($input['version']??$before['version'],1,PHP_INT_MAX,'version');$update=$this->db->prepare('UPDATE tie_accommodation_staff_memberships SET role_key=?,status=?,version=version+1 WHERE id=? AND property_id=? AND version=?');$update->execute([$role,$status,$id,$propertyId,$version]);if($update->rowCount()!==1)throw UthengaTieErrors::validation(['version'=>'Staff access changed in another session. Refresh and retry.']);$after=$this->membership($propertyId,$id);$this->audit($propertyId,$actorId,'staff.'.strtolower($status),'staff_membership',$id,$correlationId,$before,$after);if($after['user_id'])$this->notify((string)$after['user_id'],'Accommodation access updated','Your property access is now '.$status.' as '.$role.'.');return $after;
