    public function report(string $propertyId,string $actorId,string $from,string $to): array
    {
        $property=$this->access($propertyId,$actorId,'audit.read');$range=UthengaAccommodationContracts::dates($from,$to);$this->ensureInventory($propertyId,$range['check_in'],$range['check_out']);
        $reservations=$this->db->prepare("SELECT COUNT(*) reservations,COALESCE(SUM(subtotal),0) booked_value,COALESCE(SUM(amount_paid),0) recorded_paid,COALESCE(SUM(balance_due),0) outstanding,SUM(status='CANCELLED') cancelled,SUM(status='NO_SHOW') no_shows,SUM(status='CHECKED_OUT') completed FROM tie_accommodation_reservations WHERE property_id=? AND check_in_date<? AND check_out_date>?");$reservations->execute([$propertyId,$range['check_out'],$range['check_in']]);
        $inventory=$this->db->prepare('SELECT COALESCE(SUM(capacity_rooms),0) capacity_room_nights,COALESCE(SUM(confirmed_rooms),0) sold_room_nights,COALESCE(SUM(blocked_rooms),0) blocked_room_nights FROM tie_accommodation_inventory_nights WHERE property_id=? AND stay_date>=? AND stay_date<?');$inventory->execute([$propertyId,$range['check_in'],$range['check_out']]);
        $sources=$this->db->prepare('SELECT source,COUNT(*) reservations,COALESCE(SUM(subtotal),0) booked_value FROM tie_accommodation_reservations WHERE property_id=? AND check_in_date<? AND check_out_date>? GROUP BY source ORDER BY reservations DESC');$sources->execute([$propertyId,$range['check_out'],$range['check_in']]);
        $statuses=$this->db->prepare('SELECT status,COUNT(*) reservations FROM tie_accommodation_reservations WHERE property_id=? AND check_in_date<? AND check_out_date>? GROUP BY status ORDER BY reservations DESC');$statuses->execute([$propertyId,$range['check_out'],$range['check_in']]);
        $reservationSummary=$reservations->fetch()?:[];$inventorySummary=$inventory->fetch()?:[];$capacity=(int)($inventorySummary['capacity_room_nights']??0);$sold=(int)($inventorySummary['sold_room_nights']??0);
        return ['schema_version'=>'tie-accommodation-report/v2','property'=>['id'=>$propertyId,'name'=>$property['name'],'currency'=>$property['currency']],'period'=>['from'=>$range['check_in'],'to'=>$range['check_out'],'nights'=>$range['nights']],'financial'=>['booked_value'=>(float)($reservationSummary['booked_value']??0),'recorded_paid'=>(float)($reservationSummary['recorded_paid']??0),'outstanding'=>(float)($reservationSummary['outstanding']??0)],'operations'=>['reservations'=>(int)($reservationSummary['reservations']??0),'cancelled'=>(int)($reservationSummary['cancelled']??0),'no_shows'=>(int)($reservationSummary['no_shows']??0),'completed'=>(int)($reservationSummary['completed']??0),'capacity_room_nights'=>$capacity,'sold_room_nights'=>$sold,'blocked_room_nights'=>(int)($inventorySummary['blocked_room_nights']??0),'occupancy_percent'=>$capacity?round($sold/$capacity*100,1):null],'sources'=>$sources->fetchAll(),'statuses'=>$statuses->fetchAll(),'generated_at'=>gmdate('c')];
    }

    public function auditLog(string $propertyId,string $actorId): array
    {
        $this->access($propertyId,$actorId,'audit.read');$a=$this->db->prepare('SELECT e.id,e.actor_id,u.name actor_name,e.action_key,e.entity_type,e.entity_id,e.correlation_id,e.created_at FROM tie_accommodation_audit_events e LEFT JOIN users u ON u.id=e.actor_id WHERE e.property_id=? ORDER BY e.created_at DESC,e.id DESC LIMIT 250');$a->execute([$propertyId]);$refunds=$this->db->prepare('SELECT * FROM tie_accommodation_refund_requests WHERE property_id=? ORDER BY created_at DESC LIMIT 100');$refunds->execute([$propertyId]);return ['schema_version'=>'tie-accommodation-audit/v2','events'=>$a->fetchAll(),'refund_requests'=>$refunds->fetchAll()];
