    private function createUnitBlock(string $propertyId,string $actorId,array $unit,string $taskId,string $start,string $end): void
    {
        $range=UthengaAccommodationContracts::dates($start,$end);
        $existing=$this->db->prepare("SELECT COUNT(*) FROM tie_accommodation_unit_blocks WHERE unit_id=? AND status='ACTIVE' FOR UPDATE");
        $existing->execute([$unit['id']]);
        if((int)$existing->fetchColumn()>0) throw UthengaTieErrors::validation(['unit_id'=>'This physical room already has an active inventory block.']);
        $this->ensureInventory($propertyId,$range['check_in'],$range['check_out']);
        foreach($range['dates'] as $date){
            $blocked=$this->db->prepare('UPDATE tie_accommodation_inventory_nights SET maintenance_blocked_rooms=maintenance_blocked_rooms+1,blocked_rooms=blocked_rooms+1,version=version+1 WHERE room_type_id=? AND stay_date=? AND capacity_rooms-blocked_rooms-held_rooms-confirmed_rooms>=1');
            $blocked->execute([$unit['room_type_id'],$date]);
            if($blocked->rowCount()!==1) throw UthengaTieErrors::validation(['maintenance'=>'The room cannot be removed from sale because inventory is already fully committed on '.$date.'. Reassign or cancel the affected stay first.']);
        }
        $this->db->prepare('INSERT INTO tie_accommodation_unit_blocks (id,property_id,unit_id,room_type_id,task_id,start_date,end_date,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$this->uuid(),$propertyId,$unit['id'],$unit['room_type_id'],$taskId,$range['check_in'],$range['check_out'],$actorId]);
    }

    private function releaseUnitBlock(string $taskId,string $actorId,string $status): void
    {
        $query=$this->db->prepare("SELECT * FROM tie_accommodation_unit_blocks WHERE task_id=? AND status='ACTIVE' LIMIT 1 FOR UPDATE");
        $query->execute([$taskId]);$block=$query->fetch();if(!is_array($block))return;
        $range=UthengaAccommodationContracts::dates($block['start_date'],$block['end_date']);
        foreach($range['dates'] as $date)$this->db->prepare('UPDATE tie_accommodation_inventory_nights SET maintenance_blocked_rooms=GREATEST(0,maintenance_blocked_rooms-1),blocked_rooms=GREATEST(0,blocked_rooms-1),version=version+1 WHERE room_type_id=? AND stay_date=?')->execute([$block['room_type_id'],$date]);
        $this->db->prepare('UPDATE tie_accommodation_unit_blocks SET status=?,released_by=?,released_at=UTC_TIMESTAMP() WHERE id=? AND status="ACTIVE"')->execute([$status,$actorId,$block['id']]);
    }

    private function ensureInventory(string $propertyId,string $from,string $to): void
    {
        $range=UthengaAccommodationContracts::dates($from,$to);$rooms=$this->db->prepare('SELECT id,total_rooms FROM room_types WHERE property_id=? AND is_active=1 ORDER BY id');$rooms->execute([$propertyId]);$insert=$this->db->prepare('INSERT IGNORE INTO tie_accommodation_inventory_nights (property_id,room_type_id,stay_date,capacity_rooms) VALUES (?,?,?,?)');foreach($rooms->fetchAll() as $room)foreach($range['dates'] as $date)$insert->execute([$propertyId,$room['id'],$date,$room['total_rooms']]);
    }

    private function quoteProperty(string $propertyId,int $roomTypeId,int $quantity,string $checkIn,string $checkOut,bool $requirePublished=false,bool $lock=false,?string $ratePlanId=null): array
    {
        $property=$this->propertyRow($propertyId);if($requirePublished&&!in_array($property['status'],['PUBLISHED','ACTIVE'],true))throw UthengaTieErrors::validation(['property'=>'The property is not accepting reservations.']);$room=$this->room($propertyId,$roomTypeId,$lock);$dates=UthengaAccommodationContracts::dates($checkIn,$checkOut);$this->ensureInventory($propertyId,$dates['check_in'],$dates['check_out']);
        if($ratePlanId!==null)$rate=$this->ratePlan($propertyId,$ratePlanId,$lock);else{$r=$this->db->prepare('SELECT rp.*,cp.name cancellation_policy_name,cp.free_cancel_hours,cp.penalty_percent,cp.no_show_percent FROM tie_accommodation_rate_plans rp INNER JOIN tie_accommodation_cancellation_policies cp ON cp.id=rp.cancellation_policy_id WHERE rp.property_id=? AND rp.room_type_id=? AND rp.is_active=1 ORDER BY rp.created_at LIMIT 1'.($lock?' FOR UPDATE':''));$r->execute([$propertyId,$roomTypeId]);$rate=$r->fetch();if(!is_array($rate))throw UthengaTieErrors::validation(['rate_plan'=>'No active rate plan exists for this room type.']);}
        if((int)$rate['room_type_id']!==$roomTypeId)throw UthengaTieErrors::validation(['rate_plan'=>'The rate plan does not belong to this room type.']);if($dates['nights']<(int)$rate['minimum_stay']||$dates['nights']>(int)$rate['maximum_stay'])throw UthengaTieErrors::validation(['stay'=>'The selected rate requires '.$rate['minimum_stay'].' to '.$rate['maximum_stay'].' nights.']);
        $placeholders=implode(',',array_fill(0,count($dates['dates']),'?'));$sql="SELECT * FROM tie_accommodation_inventory_nights WHERE room_type_id=? AND stay_date IN ({$placeholders}) ORDER BY stay_date".($lock?' FOR UPDATE':'');$s=$this->db->prepare($sql);$s->execute(array_merge([$roomTypeId],$dates['dates']));$rows=$s->fetchAll();if(count($rows)!==$dates['nights'])throw UthengaTieErrors::providerUnavailable('accommodation_inventory');$total=0.0;$nightly=[];foreach($rows as $row){$available=max(0,(int)$row['capacity_rooms']-(int)$row['blocked_rooms']-(int)$row['held_rooms']-(int)$row['confirmed_rooms']);if((int)$row['closed']===1||$available<$quantity)throw UthengaTieErrors::validation(['inventory'=>'The selected room type is unavailable on '.$row['stay_date'].'.']);$price=$row['rate_override']!==null?(float)$row['rate_override']:(float)$rate['base_rate'];$total+=$price*$quantity;$nightly[]=['date'=>$row['stay_date'],'rate'=>$price,'sellable'=>$available,'version'=>(int)$row['version']];}
        $deposit=$rate['payment_mode']==='DEPOSIT'?round($total*((float)$rate['deposit_percent']/100),2):round($total,2);return ['property_id'=>$propertyId,'listing_id'=>$property['listing_id'],'room_type_id'=>$roomTypeId,'quantity'=>$quantity,'check_in'=>$dates['check_in'],'check_out'=>$dates['check_out'],'nights'=>$dates['nights'],'dates'=>$dates['dates'],'nightly'=>$nightly,'total'=>round($total,2),'deposit_required'=>$deposit,'balance_due'=>round($total,2),'currency'=>$property['currency'],'rate_plan'=>$rate,'room'=>$room];
    }

    private function createReservationFromBooking(string $propertyId,string $bookingId,int $roomTypeId,int $quantity,string $checkIn,string $checkOut,string $actorId): void
    {
        $exists=$this->db->prepare('SELECT id FROM tie_accommodation_reservations WHERE booking_id=? LIMIT 1');$exists->execute([$bookingId]);if($exists->fetchColumn())return;$booking=$this->db->prepare('SELECT * FROM bookings WHERE id=? LIMIT 1 FOR UPDATE');$booking->execute([$bookingId]);$b=$booking->fetch();if(!is_array($b))throw UthengaTieErrors::validation(['booking'=>'The confirmed marketplace booking was not found.']);$details=json_decode((string)($b['details']??'{}'),true)?:[];$dates=UthengaAccommodationContracts::dates($checkIn,$checkOut);$rate=$this->db->prepare('SELECT rp.*,cp.name cancellation_policy_name,cp.free_cancel_hours,cp.penalty_percent,cp.no_show_percent FROM tie_accommodation_rate_plans rp INNER JOIN tie_accommodation_cancellation_policies cp ON cp.id=rp.cancellation_policy_id WHERE rp.property_id=? AND rp.room_type_id=? AND rp.is_active=1 ORDER BY rp.created_at LIMIT 1');$rate->execute([$propertyId,$roomTypeId]);$rp=$rate->fetch();if(!is_array($rp))throw UthengaTieErrors::validation(['rate_plan'=>'No active rate plan exists for the confirmed room.']);$total=(float)$b['total_price'];$quote=['total'=>$total,'deposit_required'=>$rp['payment_mode']==='DEPOSIT'?round($total*((float)$rp['deposit_percent']/100),2):$total,'amount_paid'=>(float)($details['amount_paid']??$total),'currency'=>$b['currency']?:APP_CURRENCY,'rate_plan'=>$rp,'room_type_id'=>$roomTypeId,'nights'=>$dates['nights']];$status=$rp['booking_mode']==='REQUEST'?'PENDING_APPROVAL':'CONFIRMED';$reservation=$this->insertReservation($propertyId,$bookingId,'UTHENGA',$status,(string)$b['payment_status'],$quote,$dates,$quantity,1,0,(string)$b['customer_name'],(string)$b['customer_email'],'','',(string)($b['vendor_notes']??''),$actorId?:'system');$this->audit($propertyId,$actorId?:'system','reservation.payment_confirmed','reservation',$reservation['id'],UthengaTieObservability::requestId(),null,$reservation);
    }

    private function insertReservation(string $propertyId,string $bookingId,string $source,string $status,string $paymentStatus,array $quote,array $dates,int $quantity,int $adults,int $children,string $guestName,string $guestEmail,string $guestPhone,string $guestNotes,string $vendorNotes,string $actorId): array
    {
        $id=$this->uuid();$code='RES-'.strtoupper(bin2hex(random_bytes(5)));$rate=$quote['rate_plan'];$paid=isset($quote['amount_paid'])?(float)$quote['amount_paid']:(strtolower($paymentStatus)==='paid'?(float)$quote['total']:0.0);$balance=max(0,(float)$quote['total']-$paid);$policy=['id'=>$rate['cancellation_policy_id'],'name'=>$rate['cancellation_policy_name']??'Policy','free_cancel_hours'=>(int)$rate['free_cancel_hours'],'penalty_percent'=>(float)$rate['penalty_percent'],'no_show_percent'=>(float)$rate['no_show_percent']];$this->db->prepare('INSERT INTO tie_accommodation_reservations (id,property_id,booking_id,reservation_code,source,status,payment_status,currency,subtotal,deposit_required,amount_paid,balance_due,check_in_date,check_out_date,adults,children,guest_name,guest_email,guest_phone,guest_notes,vendor_notes,cancellation_policy_snapshot,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$propertyId,$bookingId,$code,$source,$status,$paymentStatus,$quote['currency'],(float)$quote['total'],(float)$quote['deposit_required'],$paid,$balance,$dates['check_in'],$dates['check_out'],$adults,$children,$guestName,$guestEmail?:null,$guestPhone?:null,$guestNotes?:null,$vendorNotes?:null,json_encode($policy),$actorId]);$nightly=(float)$quote['total']/max(1,$dates['nights']*$quantity);$snapshot=['rate_plan_id'=>$rate['id'],'rate_plan_name'=>$rate['name'],'booking_mode'=>$rate['booking_mode'],'payment_mode'=>$rate['payment_mode'],'deposit_percent'=>$rate['deposit_percent'],'nights'=>$dates['nights'],'currency'=>$quote['currency']];$this->db->prepare('INSERT INTO tie_accommodation_reservation_rooms (reservation_id,room_type_id,rate_plan_id,quantity,nightly_rate,line_total,rate_snapshot) VALUES (?,?,?,?,?,?,?)')->execute([$id,$quote['room_type_id'],$rate['id'],$quantity,round($nightly,2),(float)$quote['total'],json_encode($snapshot)]);return array_merge($this->reservationRow($id),$this->reservationLine($id));
    }

    private function releaseReservationNights(array $reservation,array $line,bool $futureOnly=false): void
    {
        $dates=UthengaAccommodationContracts::dates($reservation['check_in_date'],$reservation['check_out_date']);foreach($dates['dates'] as $date){if($futureOnly&&$date<gmdate('Y-m-d'))continue;$u=$this->db->prepare('UPDATE tie_accommodation_inventory_nights SET confirmed_rooms=GREATEST(0,confirmed_rooms-?),version=version+1 WHERE room_type_id=? AND stay_date=?');$u->execute([(int)$line['quantity'],$line['room_type_id'],$date]);}
    }

    private function createRefundRequestIfNeeded(string $propertyId,string $actorId,array $reservation,string $reason): void
    {
        $policy=json_decode((string)($reservation['cancellation_policy_snapshot']??'{}'),true)?:[];$checkIn=strtotime($reservation['check_in_date'].' 00:00:00 UTC');$hours=max(0,($checkIn-time())/3600);$penalty=$hours>=(int)($policy['free_cancel_hours']??0)?0:(float)($policy['penalty_percent']??100);$fee=round((float)$reservation['subtotal']*$penalty/100,2);$refund=max(0,round((float)$reservation['amount_paid']-$fee,2));if($refund<=0)return;$risk=$refund>1000000?'EXCEPTION':'STANDARD';$this->db->prepare('INSERT INTO tie_accommodation_refund_requests (id,property_id,reservation_id,requested_by,amount,currency,reason,risk_level,status) VALUES (?,?,?,?,?,?,?,?,"PENDING")')->execute([$this->uuid(),$propertyId,$reservation['id'],$actorId,$refund,$reservation['currency'],$reason,$risk]);
    }

    private function reservationRow(string $id,bool $lock=false): array {$s=$this->db->prepare('SELECT * FROM tie_accommodation_reservations WHERE id=? LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::authorization();return $r;}
    private function reservationLine(string $id): array {$s=$this->db->prepare('SELECT rr.*,rt.room_name,rp.name rate_plan_name FROM tie_accommodation_reservation_rooms rr INNER JOIN room_types rt ON rt.id=rr.room_type_id INNER JOIN tie_accommodation_rate_plans rp ON rp.id=rr.rate_plan_id WHERE rr.reservation_id=? ORDER BY rr.id LIMIT 1');$s->execute([$id]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::providerUnavailable('accommodation_reservation_room');unset($r['id'],$r['reservation_id']);return $r;}
    private function publicReservation(array $r): array {return ['id'=>(string)$r['id'],'booking_id'=>$r['booking_id']?:null,'code'=>(string)$r['reservation_code'],'source'=>(string)$r['source'],'status'=>(string)$r['status'],'payment_status'=>(string)$r['payment_status'],'currency'=>(string)$r['currency'],'subtotal'=>(float)$r['subtotal'],'deposit_required'=>(float)$r['deposit_required'],'amount_paid'=>(float)$r['amount_paid'],'balance_due'=>(float)$r['balance_due'],'check_in_date'=>(string)$r['check_in_date'],'check_out_date'=>(string)$r['check_out_date'],'adults'=>(int)$r['adults'],'children'=>(int)$r['children'],'guest_name'=>(string)$r['guest_name'],'guest_email'=>$r['guest_email']?:null,'guest_phone'=>$r['guest_phone']?:null,'room_type_id'=>(int)($r['room_type_id']??0),'room_name'=>(string)($r['room_name']??''),'rate_plan_id'=>(string)($r['rate_plan_id']??''),'rate_plan_name'=>(string)($r['rate_plan_name']??''),'quantity'=>(int)($r['quantity']??0),'assigned_units'=>(string)($r['assigned_units']??''),'version'=>(int)$r['version'],'created_at'=>(string)$r['created_at']];}
    private function task(string $propertyId,string $id,bool $lock=false): array {$s=$this->db->prepare('SELECT * FROM tie_accommodation_unit_tasks WHERE id=? AND property_id=? LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::authorization();return $r;}
    private function membership(string $propertyId,string $id): array {$s=$this->db->prepare('SELECT m.*,u.name user_name FROM tie_accommodation_staff_memberships m LEFT JOIN users u ON u.id=m.user_id WHERE m.id=? AND m.property_id=? LIMIT 1');$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::authorization();return $r;}
    private function idempotentResult(string $actor,string $action,string $key,string $hash): ?array {$s=$this->db->prepare('SELECT request_hash,response_json FROM tie_accommodation_idempotency WHERE actor_id=? AND action_key=? AND idempotency_key=? LIMIT 1');$s->execute([$actor,$action,$key]);$r=$s->fetch();if(!is_array($r))return null;if(!hash_equals((string)$r['request_hash'],$hash))throw UthengaTieErrors::validation(['idempotency_key'=>'This key was already used for a different request.']);return json_decode((string)$r['response_json'],true)?:[];}
    private function storeIdempotent(string $actor,string $action,string $key,string $hash,array $response): void {$this->db->prepare('INSERT IGNORE INTO tie_accommodation_idempotency (actor_id,action_key,idempotency_key,request_hash,response_json) VALUES (?,?,?,?,?)')->execute([$actor,$action,$key,$hash,json_encode($response)]);}
    private function notify(string $userId,string $title,string $body): void {if(!UthengaTieFeatureFlags::enabled('notifications'))return;try{(new UthengaTieNotificationOutbox($this->db))->enqueue($userId,['channel'=>'in_app','title'=>$title,'body'=>$body]);}catch(Throwable $ignore){}}

    private function access(string $propertyId,string $actorId,string $permission,bool $lock=false): array
    {
        $sql="SELECT p.*,CASE WHEN p.vendor_id=? THEN 'OWNER' ELSE m.role_key END access_role FROM tie_accommodation_properties p LEFT JOIN tie_accommodation_staff_memberships m ON m.property_id=p.id AND m.user_id=? AND m.status='ACTIVE' WHERE p.id=? AND (p.vendor_id=? OR m.user_id=?) LIMIT 1".($lock?' FOR UPDATE':'');
        $stmt=$this->db->prepare($sql);$stmt->execute([$actorId,$actorId,$propertyId,$actorId,$actorId]);$row=$stmt->fetch();if(!is_array($row)||!UthengaAccommodationPermissions::allows((string)$row['access_role'],$permission))throw UthengaTieErrors::authorization();return $row;
    }

    private function propertyRow(string $id): array {$s=$this->db->prepare('SELECT * FROM tie_accommodation_properties WHERE id=? LIMIT 1');$s->execute([$id]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::authorization();return $r;}
    private function room(string $propertyId,int $id,bool $lock=false): array {$s=$this->db->prepare('SELECT * FROM room_types WHERE id=? AND property_id=? AND is_active=1 LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::validation(['room_type_id'=>'Choose an active room type for this property.']);return $r;}
    private function ratePlan(string $propertyId,string $id,bool $lock=false): array {$s=$this->db->prepare('SELECT rp.*,cp.name cancellation_policy_name,cp.free_cancel_hours,cp.penalty_percent,cp.no_show_percent FROM tie_accommodation_rate_plans rp INNER JOIN tie_accommodation_cancellation_policies cp ON cp.id=rp.cancellation_policy_id WHERE rp.id=? AND rp.property_id=? AND rp.is_active=1 LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::validation(['rate_plan_id'=>'Choose an active rate plan.']);return $r;}
    private function policy(string $propertyId,string $id,bool $lock=false): array {$s=$this->db->prepare('SELECT * FROM tie_accommodation_cancellation_policies WHERE id=? AND property_id=? AND is_active=1 LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::validation(['cancellation_policy_id'=>'Choose an active cancellation policy.']);return $r;}
    private function unit(string $propertyId,string $id,bool $lock=false): array {$s=$this->db->prepare('SELECT u.*,rt.room_name FROM tie_accommodation_units u INNER JOIN room_types rt ON rt.id=u.room_type_id WHERE u.id=? AND u.property_id=? AND u.is_active=1 LIMIT 1'.($lock?' FOR UPDATE':''));$s->execute([$id,$propertyId]);$r=$s->fetch();if(!is_array($r))throw UthengaTieErrors::validation(['unit_id'=>'Choose an active physical room.']);return $r;}
    private function publicProperty(array $r): array {$role=(string)($r['access_role']??'OWNER');return ['id'=>(string)$r['id'],'name'=>(string)$r['name'],'vendor_id'=>(string)$r['vendor_id'],'listing_id'=>$r['listing_id']?:null,'service_profile_id'=>$r['service_profile_id']?:null,'property_type'=>(string)$r['property_type'],'description'=>(string)($r['description']??''),'address'=>(string)$r['address'],'city'=>$r['city']?:null,'timezone'=>(string)$r['timezone'],'currency'=>(string)$r['currency'],'phone'=>$r['phone']?:null,'email'=>$r['email']?:null,'image_url'=>$r['image_url']?:null,'check_in_time'=>(string)$r['check_in_time'],'check_out_time'=>(string)$r['check_out_time'],'status'=>(string)$r['status'],'version'=>(int)$r['version'],'access_role'=>$role,'access_capabilities'=>UthengaAccommodationPermissions::capabilities($role)];}
    private function time($value): string {$value=trim((string)$value);if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/',$value))throw UthengaTieErrors::validation(['time'=>'Use a valid 24-hour time.']);return strlen($value)===5?$value.':00':$value;}
    private function audit(string $propertyId,string $actorId,string $action,string $type,string $id,string $correlationId,?array $before,?array $after): void {$this->db->prepare('INSERT INTO tie_accommodation_audit_events (property_id,actor_id,action_key,entity_type,entity_id,correlation_id,before_state,after_state) VALUES (?,?,?,?,?,?,?,?)')->execute([$propertyId,$actorId,$action,$type,$id,$correlationId,$before?json_encode($this->redact($before)):null,$after?json_encode($this->redact($after)):null]);}
    private function redact(array $data): array {foreach(['password','password_hash','api_key','secret','guest_notes'] as $key)unset($data[$key]);return $data;}
    private function uuid(): string {$b=random_bytes(16);$b[6]=chr((ord($b[6])&0x0f)|0x40);$b[8]=chr((ord($b[8])&0x3f)|0x80);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}
}
